using Payments;

namespace PaymentGateway.Tests;

[TestClass]
public class PaymentGatewayChargeTests
{
    private Payments.PaymentGateway _gateway = null!;

    [TestInitialize]
    public void Setup()
    {
        _gateway = new Payments.PaymentGateway();
    }

    [TestMethod]
    [DataRow("tok_valid_visa", 10.00)]
    [DataRow("tok_valid_mastercard", 99.99)]
    [DataRow("tok_valid_amex", 0.01)]
    public async Task ChargeAsync_ValidTokenAndAmount_ReturnsSuccessWithChargeId(string token, double amount)
    {
        var result = await _gateway.ChargeAsync(token, (decimal)amount);

        Assert.IsNotNull(result);
        Assert.IsTrue(result.Success);
        Assert.IsFalse(string.IsNullOrWhiteSpace(result.ChargeId));
    }

    [TestMethod]
    [DataRow("", 50.00)]
    [DataRow(null, 50.00)]
    public async Task ChargeAsync_InvalidToken_ThrowsArgumentException(string? token, double amount)
    {
        await Assert.ThrowsExceptionAsync<ArgumentException>(
            () => _gateway.ChargeAsync(token!, (decimal)amount));
    }

    [TestMethod]
    [DataRow("tok_valid", 0.00)]
    [DataRow("tok_valid", -10.00)]
    [DataRow("tok_valid", -0.01)]
    public async Task ChargeAsync_ZeroOrNegativeAmount_ThrowsArgumentOutOfRangeException(string token, double amount)
    {
        await Assert.ThrowsExceptionAsync<ArgumentOutOfRangeException>(
            () => _gateway.ChargeAsync(token, (decimal)amount));
    }

    [TestMethod]
    public async Task ChargeAsync_VeryLargeAmount_ReturnsFailure()
    {
        var result = await _gateway.ChargeAsync("tok_valid", 1_000_000_000m);

        Assert.IsNotNull(result);
        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_DeclinedCard_ReturnsFailureResult()
    {
        var result = await _gateway.ChargeAsync("tok_declined", 25.00m);

        Assert.IsNotNull(result);
        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_MultipleCharges_ReturnUniqueChargeIds()
    {
        var result1 = await _gateway.ChargeAsync("tok_valid", 10.00m);
        var result2 = await _gateway.ChargeAsync("tok_valid", 20.00m);

        Assert.AreNotEqual(result1.ChargeId, result2.ChargeId);
    }
}

[TestClass]
public class PaymentGatewayRefundTests
{
    private Payments.PaymentGateway _gateway = null!;

    [TestInitialize]
    public void Setup()
    {
        _gateway = new Payments.PaymentGateway();
    }

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccessWithRefundId()
    {
        var chargeResult = await _gateway.ChargeAsync("tok_valid", 50.00m);

        var refundResult = await _gateway.RefundAsync(chargeResult.ChargeId);

        Assert.IsNotNull(refundResult);
        Assert.IsTrue(refundResult.Success);
        Assert.IsFalse(string.IsNullOrWhiteSpace(refundResult.RefundId));
    }

    [TestMethod]
    [DataRow("")]
    [DataRow(null)]
    public async Task RefundAsync_InvalidChargeId_ThrowsArgumentException(string? chargeId)
    {
        await Assert.ThrowsExceptionAsync<ArgumentException>(
            () => _gateway.RefundAsync(chargeId!));
    }

    [TestMethod]
    public async Task RefundAsync_NonExistentChargeId_ReturnsFailure()
    {
        var result = await _gateway.RefundAsync("ch_nonexistent_12345");

        Assert.IsNotNull(result);
        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public async Task RefundAsync_AlreadyRefundedCharge_ReturnsFailure()
    {
        var chargeResult = await _gateway.ChargeAsync("tok_valid", 30.00m);
        await _gateway.RefundAsync(chargeResult.ChargeId);

        var secondRefund = await _gateway.RefundAsync(chargeResult.ChargeId);

        Assert.IsNotNull(secondRefund);
        Assert.IsFalse(secondRefund.Success);
    }

    [TestMethod]
    public async Task RefundAsync_MultipleRefunds_ReturnUniqueRefundIds()
    {
        var charge1 = await _gateway.ChargeAsync("tok_valid", 10.00m);
        var charge2 = await _gateway.ChargeAsync("tok_valid", 20.00m);

        var refund1 = await _gateway.RefundAsync(charge1.ChargeId);
        var refund2 = await _gateway.RefundAsync(charge2.ChargeId);

        Assert.AreNotEqual(refund1.RefundId, refund2.RefundId);
    }
}

